        },
        {
            "id": "f001",
            "name": "facility_distance",
            "rows": [
                {"Facility": "F1", "N1": "2", "N10": "12", "N2": "3", "N3": "5", "N4": "9", "N5": "10", "N6": "11", "N7": "13", "N8": "14", "N9": "15"},
                {"Facility": "F2", "N1": "4", "N10": "11", "N2": "2", "N3": "3", "N4": "8", "N5": "9", "N6": "10", "N7": "12", "N8": "13", "N9": "14"},
                {"Facility": "F3", "N1": "9", "N10": "7", "N2": "8", "N3": "4", "N4": "2", "N5": "3", "N6": "5", "N7": "9", "N8": "10", "N9": "11"},
                {"Facility": "F4", "N1": "10", "N10": "6", "N2": "9", "N3": "6", "N4": "3", "N5": "2", "N6": "3", "N7": "8", "N8": "9", "N9": "10"},
                {"Facility": "F5", "N1": "13", "N10": "5", "N2": "12", "N3": "10", "N4": "8", "N5": "7", "N6": "6", "N7": "2", "N8": "3", "N9": "4"},
                {"Facility": "F6", "N1": "12", "N10": "2", "N2": "11", "N3": "8", "N4": "7", "N5": "6", "N6": "5", "N7": "5", "N8": "4", "N9": "3"}
            ]
        },
        {
            "id": "f002",
            "name": "planning_parameters",
            "rows": [
                {"Parameter": "NumberOfFacilitiesToOpen", "Value": "2"}
            ]
        }
    ]
}

def solve_problem():
    tables = data["tables"]

    def get_table(table_id):
        for t in tables:
            if t.get("id") == table_id:
                return t
        raise KeyError(f"Table with id '{table_id}' not found")

    table_neigh = get_table("f000")
    table_fac = get_table("f001")
    table_param = get_table("f002")

    # Extract neighborhoods and demand
    neighborhoods = []
    demand = {}
    for rec in table_neigh["rows"]:
        neigh = rec["Neighborhood"]
        dem = int(rec["Demand"])
        neighborhoods.append(neigh)
        demand[neigh] = dem

    # Extract facilities and distances
    facilities = []
    distances = {}
    for rec in table_fac["rows"]:
        fac = rec["Facility"]
        facilities.append(fac)
        distances[fac] = {}
        for neigh in neighborhoods:
            if neigh not in rec:
                raise ValueError(f"Missing distance for facility {fac} to neighborhood {neigh}")
            distances[fac][neigh] = int(rec[neigh])

    # Extract number of facilities to open
    P = None
    for rec in table_param["rows"]:
        if rec["Parameter"] == "NumberOfFacilitiesToOpen":
            P = int(rec["Value"])
            break
    if P is None:
        raise ValueError("NumberOfFacilitiesToOpen parameter not found")

    # Build the PuLP model
    prob = pulp.LpProblem("p_median", pulp.LpMinimize)

    # Decision variables
    y = pulp.LpVariable.dicts("y", facilities, lowBound=0, upBound=1, cat="Binary")
    x = pulp.LpVariable.dicts(
        "x",
        [(i, j) for i in facilities for j in neighborhoods],
        lowBound=0,
        upBound=1,
        cat="Binary",
    )

    # Objective: minimize demand-weighted distance
    prob += pulp.lpSum(
        demand[j] * distances[i][j] * x[(i, j)] for i in facilities for j in neighborhoods
    )

    # Constraints
    # Each neighborhood assigned to exactly one facility
    for j in neighborhoods:
        prob += pulp.lpSum(x[(i, j)] for i in facilities) == 1, f"assign_{j}"

    # Exactly P facilities opened
    prob += pulp.lpSum(y[i] for i in facilities) == P, "open_facilities"

    # Assignment only to opened facilities
    for i in facilities:
        for j in neighborhoods:
            prob += x[(i, j)] <= y[i], f"link_{i}_{j}"

    # Solve the model
    prob.solve(pulp.PULP_CBC_CMD(msg=False))

    return prob

# Expose the model
m = solve_problem()
